-- AlterTable: Изменение типа поля description с TEXT на JSON для хранения BlockNote документов
-- Migration generated by prisma migrate

-- Изменяем тип поля description с TEXT на JSONB
-- JSONB более эффективен чем JSON для PostgreSQL (поддержка индексов и быстрый поиск)
ALTER TABLE "events" ALTER COLUMN "description" TYPE JSONB USING CASE 
  WHEN "description" IS NULL THEN NULL
  WHEN "description" = '' THEN NULL
  ELSE (
    '{"blocks": [{"id": "' || substr(md5(random()::text), 0, 8) || '", "type": "paragraph", "props": {}, "content": [{"type": "text", "text": ' || 
    to_json("description")::text || 
    ', "styles": {}}], "children": []}]}'
  )::JSONB
END;

-- Комментарий для документирования изменения
COMMENT ON COLUMN "events"."description" IS 'BlockNote document JSON (array of Block objects)';
